#ifndef FAST_VECTOR_MATH_H
#define FAST_VECTOR_MATH_H

#include <godot_cpp/classes/ref_counted.hpp>
#include <godot_cpp/variant/vector3.hpp>
#include <godot_cpp/variant/array.hpp>
#include <godot_cpp/variant/packed_vector3_array.hpp>

namespace godot {

class FastVectorMath : public RefCounted {
    GDCLASS(FastVectorMath, RefCounted)

protected:
    static void _bind_methods();

public:
    static real_t dot_product(Vector3 a, Vector3 b);
    static Vector3 cross_product(Vector3 a, Vector3 b);
    static Array compute_centroid_and_bounds(const PackedVector3Array &points);
    static real_t ray_sphere_intersection(Vector3 origin, Vector3 dir, Vector3 sphere_center, real_t radius);
};

}

#endif

#include "fast_vector_math.h"
#include <godot_cpp/core/class_db.hpp>
#include <godot_cpp/variant/utility_functions.hpp>
#include <algorithm>
#include <cmath>

namespace godot {

void FastVectorMath::_bind_methods() {
    ClassDB::bind_static_method("FastVectorMath", D_METHOD("dot_product", "a", "b"), &FastVectorMath::dot_product);
    ClassDB::bind_static_method("FastVectorMath", D_METHOD("cross_product", "a", "b"), &FastVectorMath::cross_product);
    ClassDB::bind_static_method("FastVectorMath", D_METHOD("compute_centroid_and_bounds", "points"), &FastVectorMath::compute_centroid_and_bounds);
    ClassDB::bind_static_method("FastVectorMath", D_METHOD("ray_sphere_intersection", "origin", "dir", "sphere_center", "radius"), &FastVectorMath::ray_sphere_intersection);
}

real_t FastVectorMath::dot_product(Vector3 a, Vector3 b) {
    return a.dot(b);
}

Vector3 FastVectorMath::cross_product(Vector3 a, Vector3 b) {
    return a.cross(b);
}

Array FastVectorMath::compute_centroid_and_bounds(const PackedVector3Array &points) {
    if (points.is_empty()) {
        return Array::make(Vector3(0, 0, 0), Vector3(0, 0, 0), Vector3(0, 0, 0));
    }
    Vector3 sum = Vector3(0, 0, 0);
    Vector3 min_b = points[0];
    Vector3 max_b = points[0];
    for (int i = 0; i < points.size(); ++i) {
        Vector3 p = points[i];
        sum += p;
        min_b.x = std::min(min_b.x, p.x);
        min_b.y = std::min(min_b.y, p.y);
        min_b.z = std::min(min_b.z, p.z);
        max_b.x = std::max(max_b.x, p.x);
        max_b.y = std::max(max_b.y, p.y);
        max_b.z = std::max(max_b.z, p.z);
    }
    return Array::make(sum / (real_t)points.size(), min_b, max_b);
}

real_t FastVectorMath::ray_sphere_intersection(Vector3 origin, Vector3 dir, Vector3 sphere_center, real_t radius) {
    Vector3 oc = origin - sphere_center;
    real_t a = dir.dot(dir);
    real_t b = 2.0 * oc.dot(dir);
    real_t c = oc.dot(oc) - radius * radius;
    real_t discriminant = b * b - 4.0 * a * c;
    if (discriminant < 0) return -1.0;
    real_t t = (-b - std::sqrt(discriminant)) / (2.0 * a);
    return (t >= 0) ? t : -1.0;
}

}

