extends SceneTree

func _init():
	var math = ClassDB.instantiate("FastVectorMath")
	var passed_all = true

	# 1. dot_product
	var d = math.dot_product(Vector3(1, 2, 3), Vector3(4, 5, 6))
	if abs(d - 32.0) < 0.001:
		print("PASS: dot_product")
	else:
		print("FAIL: dot_product (expected 32.0, got %f)" % d)
		passed_all = false

	# 2. cross_product
	var c = math.cross_product(Vector3(1, 0, 0), Vector3(0, 1, 0))
	if c.is_equal_approx(Vector3(0, 0, 1)):
		print("PASS: cross_product")
	else:
		print("FAIL: cross_product (expected (0,0,1), got %s)" % c)
		passed_all = false

	# 3. compute_centroid_and_bounds
	var pts = PackedVector3Array([Vector3(0, 0, 0), Vector3(2, 2, 2)])
	var r = math.compute_centroid_and_bounds(pts)
	if r.size() == 3 and r[0].is_equal_approx(Vector3(1, 1, 1)) and r[1].is_equal_approx(Vector3(0, 0, 0)) and r[2].is_equal_approx(Vector3(2, 2, 2)):
		print("PASS: compute_centroid_and_bounds")
	else:
		print("FAIL: compute_centroid_and_bounds (expected [(1,1,1), (0,0,0), (2,2,2)], got %s)" % [r[0], r[1], r[2]])
		passed_all = false

	# 4. ray_sphere_intersection
	var t = math.ray_sphere_intersection(Vector3(0, 0, 5), Vector3(0, 0, -1), Vector3(0, 0, 0), 1.0)
	if abs(t - 4.0) < 0.001:
		print("PASS: ray_sphere_intersection")
	else:
		print("FAIL: ray_sphere_intersection (expected 4.0, got %f)" % t)
		passed_all = false

	if passed_all:
		print("ALL TESTS PASSED")
		quit(0)
	else:
		quit(1)

